function ESTIMATE-D(branch_counts, survival_counts):
    b <- mean(branch_counts)
    k <- mean(survival_counts)
    assert b >= 2 and 1 <= k <= b
    D <- log(k) / log(b)
    return clamp(D, 0, 1)

function COMPOSE(stages):
    total_entropy <- 0
    worst_case_size <- 1
    for s in stages:
        assert s.b >= 2 and 1 <= s.k <= s.b and s.d >= 0
        total_entropy <- total_entropy + s.d * log(s.k)
        worst_case_size <- worst_case_size * s.b ** s.d
    return (total_entropy, worst_case_size)

