from __future__ import annotations
import math

def search_entropy(k: int, d: int) -> float:
    return math.log(k ** d)

def full_tree_entropy(b: int, d: int) -> float:
    return math.log(b ** d)

def search_dimension(b: int, k: int) -> float:
    return math.log(k) / math.log(b)

# The entropy ratio equals the dimension at every depth: d cancels.
b, k = 7, 4
for d in range(1, 6):
    ratio = search_entropy(k, d) / full_tree_entropy(b, d)
    assert abs(ratio - search_dimension(b, k)) < 1e-12
    print(f"d={d}: entropy ratio = {ratio:.6f} = D")
